import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class ContractTest{static void values(Object[]expected,Object[]actual){assertNotNull(actual);assertEquals(Arrays.stream(expected).map(TaskBinding::value).toList(),Arrays.stream(actual).map(TaskBinding::value).toList());}static Object[]select(Object[]input,Supplier<Object[]>call){Object[]refs=input.clone();var before=Arrays.stream(input).map(TaskBinding::value).toList();Object[]out=call.get();for(int i=0;i<input.length;i++)assertSame(refs[i],input[i]);assertEquals(before,Arrays.stream(input).map(TaskBinding::value).toList());return out;}@Test void duplicatesEmptyNoMatchesAndProperties(){Object a=TaskBinding.customer(1,"A","B","C","0000000000000001"),b=TaskBinding.customer(2,"A","A","Z","0000000000000002"),c=TaskBinding.customer(3,"A","A","A","0000000000000003");Object[]in=TaskBinding.array(a,b,c,b);values(new Object[]{c,b,b,a},select(in,()->TaskBinding.sorted(in)));values(new Object[]{b,b},select(in,()->TaskBinding.range(in,"0000000000000002","0000000000000002")));values(new Object[0],select(in,()->TaskBinding.range(in,"0000000000000010","0000000000000020")));Object[]empty=TaskBinding.array();values(new Object[0],select(empty,()->TaskBinding.sorted(empty)));Object shortOne=TaskBinding.shortValue(9,"Short");assertFalse(TaskBinding.text(shortOne).isBlank());TaskBinding.edit(shortOne,7,"L","F","M","A","0000000000000007","0007");assertEquals(List.of(7L,"L","F","M","A","0000000000000007","0007"),TaskBinding.value(shortOne));}}
